# For each of four unknowns, find matching row substrings based on surrounding known cells excluding the central masked 2x2
for r,c in [(19,19),(19,20),(20,19),(20,20)]:
    known=[]
    for dr in range(-3,4):
      for dc in range(-3,4):
        rr,cc=r+dr,c+dc
        if 0<=rr<30 and 0<=cc<30 and grid[rr][cc]!=6 and (rr,cc) not in [(19,19),(19,20),(20,19),(20,20)]:
          known.append((dr,dc,grid[rr][cc]))
    matches=[]
    for rr in range(3,27):
      for cc in range(3,27):
        vals=[(dr,dc,v) for dr,dc,v in known if grid[rr+dr][cc+dc]==v]
        if len(vals)>=len(known)*.7:
          matches.append((rr,cc,len(vals),len(known),grid[rr][cc]))
    print((r,c), sorted(matches,key=lambda x:-x[2])[:8], 'neighbors',[(dr,dc,v) for dr,dc,v in known if abs(dr)<=1 and abs(dc)<=1])

